-- อัปเดตตาราง result_trend จากไฟล์ 4_result_trend_webapp_with_directions.csv (77 จังหวัด)
-- ตารางเดิมเก็บไว้เป็น result_trend_backup
-- รันทั้งไฟล์ใน Supabase SQL Editor ครั้งเดียว (อยู่ใน transaction ถ้าผิดตรงไหนจะไม่เปลี่ยนอะไรเลย)

begin;

-- 1) เก็บตารางเดิมไว้เป็น backup (เปลี่ยนชื่อ primary key ด้วย ไม่งั้นชื่อชนกับตารางใหม่)
alter table public.result_trend rename to result_trend_backup;
alter table public.result_trend_backup rename constraint result_trend_pkey to result_trend_backup_pkey;

-- 2) สร้างตารางใหม่ชื่อเดิม: คอลัมน์เดิมทั้งหมด + ทิศทางแนวโน้ม 3 คอลัมน์
create table public.result_trend (
  province        text primary key,
  period          text,
  slope_recycled  double precision,
  slope_proper    double precision,
  slope_improper  double precision,
  cluster         text not null,
  cluster_name    text,
  trend_recycled  text,
  trend_proper    text,
  trend_improper  text
);

-- 3) เปิด RLS + ให้อ่านได้แบบ public เหมือนตารางเดิม (เว็บใช้ publishable key อ่าน)
alter table public.result_trend enable row level security;
create policy "public read" on public.result_trend for select using (true);

-- 4) ใส่ข้อมูลใหม่

-- 5) ผูก view province_summary กลับมาที่ตารางใหม่
--    (ตอนเปลี่ยนชื่อตารางเดิม view จะตามไปอ่าน result_trend_backup แทน จึงต้องสร้างใหม่ด้วยนิยามเดิม)
create or replace view public.province_summary with (security_invoker = true) as
 SELECT a.province,
    r.region,
    a.cluster,
    a.level_disposal,
    a.level_recycling,
    a.level_backlog,
    round(avg(r.waste_generated_tpd)::numeric, 1) AS waste_tpd,
    round((sum(r.waste_improper_tpd) * 100::double precision / sum(r.waste_generated_tpd))::numeric, 1) AS improper_pct,
    round((sum(r.waste_recycled_tpd) * 100::double precision / sum(r.waste_generated_tpd))::numeric, 1) AS recycled_pct,
    round((sum(r.waste_proper_tpd) * 100::double precision / sum(r.waste_generated_tpd))::numeric, 1) AS proper_pct,
    t.cluster AS trend_cluster,
    t.cluster_name AS trend_name
   FROM result_avg a
     JOIN raw_yearly r ON r.province = a.province
     LEFT JOIN result_trend t ON t.province = a.province
  GROUP BY a.province, r.region, a.cluster, a.level_disposal, a.level_recycling, a.level_backlog, t.cluster, t.cluster_name;

-- 6) ตรวจ: new_rows = 77, missing_in_raw = 0, view_uses_new_table = true
select
  (select count(*) from public.result_trend) as new_rows,
  (select count(*) from public.result_trend t where not exists (select 1 from public.raw_yearly r where r.province = t.province)) as missing_in_raw,
  (select count(*) from public.province_summary s join public.result_trend t on t.province = s.province and t.cluster_name = s.trend_name) = 77 as view_uses_new_table;

commit;

-- ถ้าต้องการย้อนกลับไปใช้ตารางเดิม (รันส่วนนี้แยกต่างหาก):
-- begin;
