-- alter table public.result_trend_rejected rename constraint result_trend_pkey to result_trend_rejected_pkey;
-- alter table public.result_trend_backup rename constraint result_trend_backup_pkey to result_trend_pkey;
-- alter table public.result_trend_backup rename to result_trend;
-- -- แล้วรันคำสั่ง create or replace view ในข้อ 5 ซ้ำอีกครั้ง ให้ view กลับมาอ่านตารางเดิม
-- drop table public.result_trend_rejected;
-- commit;
